 31| /**
 32|  * Representation of a Complex number, i.e. a number which has both a
 33|  * real and imaginary part.
 34|  * <br/>
 35|  * Implementations of arithmetic operations handle {@code NaN} and
 36|  * infinite values according to the rules for {@link java.lang.Double}, i.e.
 37|  * {@link #equals} is an equivalence relation for all instances that have
 38|  * a {@code NaN} in either real or imaginary part, e.g. the following are
 39|  * considered equal:
 40|  * <ul>
 41|  *  <li>{@code 1 + NaNi}</li>
 42|  *  <li>{@code NaN + i}</li>
 43|  *  <li>{@code NaN + NaNi}</li>
 44|  * </ul>
 45|  * Note that this is in contradiction with the IEEE-754 standard for floating
 46|  * point numbers (according to which the test {@code x == x} must fail if
 47|  * {@code x} is {@code NaN}). The method
 48|  * {@link org.apache.commons.math.util.Precision#equals(double,double,int)
 49|  * equals for primitive double} in {@link org.apache.commons.math.util.Precision}
 50|  * conforms with IEEE-754 while this class conforms with the standard behavior
 51|  * for Java object types.
 52|  * <br/>
 53|  * Implements Serializable since 2.0
 54|  *
 55|  * @version $Id$
 56|  */
 57| public class Complex implements FieldElement<Complex>, Serializable  {
 58|     /** The square root of -1. A number representing "0.0 + 1.0i" */
 59|     public static final Complex I = new Complex(0.0, 1.0);
 60|     // CHECKSTYLE: stop ConstantName
 61|     /** A complex number representing "NaN + NaNi" */
 62|     public static final Complex NaN = new Complex(Double.NaN, Double.NaN);
 63|     // CHECKSTYLE: resume ConstantName
 64|     /** A complex number representing "+INF + INFi" */
 65|     public static final Complex INF = new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
 66|     /** A complex number representing "1.0 + 0.0i" */
 67|     public static final Complex ONE = new Complex(1.0, 0.0);
 68|     /** A complex number representing "0.0 + 0.0i" */
 69|     public static final Complex ZERO = new Complex(0.0, 0.0);
 70| 
 71|     /** Serializable version identifier */
 72|     private static final long serialVersionUID = -6195664516687396620L;
 73| 
 74|     /** The imaginary part. */
 75|     private final double imaginary;
 76|     /** The real part. */
 77|     private final double real;
 78|     /** Record whether this complex number is equal to NaN. */
 79|     private final transient boolean isNaN;
 80|     /** Record whether this complex number is infinite. */
 81|     private final transient boolean isInfinite;
 82| 
 83|     /**
 84|      * Create a complex number given only the real part.
 85|      *
 86|      * @param real Real part.
 87|      */
 88|     public Complex(double real) {
 89|         this(real, 0.0);
 90|     }
 91| 
 92|     /**
 93|      * Create a complex number given the real and imaginary parts.
 94|      *
 95|      * @param real Real part.
 96|      * @param imaginary Imaginary part.
 97|      */
 98|     public Complex(double real, double imaginary) {
 99|         this.real = real;
100|         this.imaginary = imaginary;
101| 
102|         isNaN = Double.isNaN(real) || Double.isNaN(imaginary);
103|         isInfinite = !isNaN &&
104|             (Double.isInfinite(real) || Double.isInfinite(imaginary));
105|     }
106| 
107|     /**
108|      * Return the absolute value of this complex number.
109|      * Returns {@code NaN} if either real or imaginary part is {@code NaN}
110|      * and {@code Double.POSITIVE_INFINITY} if neither part is {@code NaN},
111|      * but at least one part is infinite.
112|      *
113|      * @return the absolute value.
114|      */
115|     public double abs() {
116|         if (isNaN) {
117|             return Double.NaN;
118|         }
119|         if (isInfinite()) {
120|             return Double.POSITIVE_INFINITY;
121|         }
122|         if (FastMath.abs(real) < FastMath.abs(imaginary)) {
123|             if (imaginary == 0.0) {
124|                 return FastMath.abs(real);
125|             }
126|             double q = real / imaginary;
127|             return FastMath.abs(imaginary) * FastMath.sqrt(1 + q * q);
128|         } else {
129|             if (real == 0.0) {
130|                 return FastMath.abs(imaginary);
131|             }
132|             double q = imaginary / real;
133|             return FastMath.abs(real) * FastMath.sqrt(1 + q * q);
134|         }
135|     }
136| 
137|     /**
138|      * Returns a {@code Complex} whose value is
139|      * {@code (this + addend)}.
140|      * Uses the definitional formula
141|      * <pre>
142|      *  <code>
143|      *   (a + bi) + (c + di) = (a+c) + (b+d)i
144|      *  </code>
145|      * </pre>
146|      * <br/>
147|      * If either {@code this} or {@code addend} has a {@code NaN} value in
148|      * either part, {@link #NaN} is returned; otherwise {@code Infinite}
149|      * and {@code NaN} values are returned in the parts of the result
150|      * according to the rules for {@link java.lang.Double} arithmetic.
151|      *
152|      * @param  addend Value to be added to this {@code Complex}.
153|      * @return {@code this + addend}.
154|      * @throws NullArgumentException if {@code addend} is {@code null}.
155|      */
156|     public Complex add(Complex addend) throws NullArgumentException {
157|         MathUtils.checkNotNull(addend);
158|         if (isNaN || addend.isNaN) {
159|             return NaN;
160|         }
161| 
162|         return createComplex(real + addend.getReal(),
163|                              imaginary + addend.getImaginary());
164|     }
165| 
166|     /**
167|      * Returns a {@code Complex} whose value is {@code (this + addend)},
168|      * with {@code addend} interpreted as a real number.
169|      *
170|      * @param addend Value to be added to this {@code Complex}.
171|      * @return {@code this + addend}.
172|      * @see #add(Complex)
173|      */
174|     public Complex add(double addend) {
175|         if (isNaN || Double.isNaN(addend)) {
176|             return NaN;
177|         }
178| 
179|         return createComplex(real + addend, imaginary);
180|     }
181| 
182|      /**
183|      * Return the conjugate of this complex number.
184|      * The conjugate of {@code a + bi} is {@code a - bi}.
185|      * <br/>
186|      * {@link #NaN} is returned if either the real or imaginary
187|      * part of this Complex number equals {@code Double.NaN}.
188|      * <br/>
189|      * If the imaginary part is infinite, and the real part is not
190|      * {@code NaN}, the returned value has infinite imaginary part
191|      * of the opposite sign, e.g. the conjugate of
192|      * {@code 1 + POSITIVE_INFINITY i} is {@code 1 - NEGATIVE_INFINITY i}.
193|      *
194|      * @return the conjugate of this Complex object.
195|      */
196|     public Complex conjugate() {
197|         if (isNaN) {
198|             return NaN;
199|         }
200| 
201|         return createComplex(real, -imaginary);

